import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';
// No need to import primitives directly since we use ctx.primitives

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Determine colors from config ---
  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? { ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10' };

  // --- Card plane ---
  const geo = new PlaneGeometry(1.6, 1); // aspect from source rect 512x320
  const mat = new MeshBasicNodeMaterial({ color: colors.surface }); // fallback, will be overridden by texture
  const card = new Mesh(geo, mat);
  group.add(card);

  // --- Load texture ---
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      mat.map = texture;
      mat.needsUpdate = true;
    });
  }

  // --- Text (Journal 2) ---
  const text = ctx.fontAtlas.createText('Journal 2', {
    fontSize: 39,
    color: colors.paper,
    align: 'center',
  });
  text.position.set(0, 0, 0.01); // slight offset above plane
  group.add(text);

  // --- Cinematic Primitive: parallax-scroll ---
  const scrollPrimitive = ctx.primitives['parallax-scroll'](group, { intensity: 0.25 });

  // --- Event Handlers ---
  group.userData.handlers = {};

  // Hover: rise-in effect (0.15 units up)
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(group.position, { y: group.position.y + 0.15, duration: 0.3, ease: 'power2.out' }, 0);

  group.userData.handlers.onPointerEnter = () => hoverTimeline.play();
  group.userData.handlers.onPointerLeave = () => hoverTimeline.reverse();

  // Click: emit hub-journal.select
  group.userData.handlers.onClick = () => {
    ctx.emit('hub-journal.select', { label: 'Journal 2' });
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Kill GSAP timelines
    hoverTimeline.kill();

    // Dispose primitive
    scrollPrimitive.cleanup();

    // Dispose geometry & material
    geo.dispose();
    mat.dispose();
    if (mat.map) mat.map.dispose();

    // Dispose text (if it provides a cleanup method)
    if (text.userData.cleanup) text.userData.cleanup();
  };

  return group;
}
